import{_ as r,o as l,c as t,a3 as i,j as e,a}from"./chunks/framework.z_KJ15Ep.js";const g="/bilder/unterricht-kataloge/kataloge-dsgvo-01.png",o="/bilder/unterricht-kataloge/kataloge-dsgvo-02.png",k=JSON.parse('{"title":"DSGVO-Einwilligungen im Katalog vorbereiten","description":"","frontmatter":{"title":"DSGVO-Einwilligungen im Katalog vorbereiten","source_pageid":257,"source_revision":5453},"headers":[],"relativePath":"schild3/unterricht-kataloge/dsgvo-einwilligungen-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/dsgvo-einwilligungen-schulbezogene-kataloge.md"}'),s={name:"schild3/unterricht-kataloge/dsgvo-einwilligungen-schulbezogene-kataloge.md"};function d(u,n,c,h,p,w){return l(),t("div",null,[...n[0]||(n[0]=[i('<h1 id="dsgvo-einwilligungen-im-katalog-vorbereiten" tabindex="-1">DSGVO-Einwilligungen im Katalog vorbereiten <a class="header-anchor" href="#dsgvo-einwilligungen-im-katalog-vorbereiten" aria-label="Permalink to &quot;DSGVO-Einwilligungen im Katalog vorbereiten&quot;">​</a></h1><p>Legen Sie die an Ihrer Schule verwendeten Einwilligungen an. Anschließend können Abfrage und Zustimmung bei Schülerinnen, Schülern und Lehrkräften dokumentiert werden.</p><p>DSGVO-Einwilligungen dienen dazu, Einwilligungen gemäß der Datenschutzgrundverordnung in die <strong>Verarbeitung personenbezogener Daten</strong> zu verwalten, die für Schülerinnen und Schüler oder von Lehrkräften erteilt wurden.</p><p>Der Katalog dokumentiert insbesondere freiwillige, auf Einwilligung gestützte Verarbeitungen. Die zulässigen schulischen Datenbestände werden durch <strong>VO-DV I und VO-DV II</strong> konkretisiert; die DSGVO ist keine Liste einzelner SchILD-Datenfelder. Rechtsgrundlagen: <a href="https://bass.schule.nrw/101.htm" target="_blank" rel="noreferrer">VO-DV I</a>, <a href="https://bass.schule.nrw/1393.htm" target="_blank" rel="noreferrer">VO-DV II</a>.</p><p>Ein Beispiel ist die Verwendung des Fotos der Schüler.</p><p>Die angelegten Einwilligungen können im Reiter <em>Schüler ➜ Einwilligungen</em> für jeden Schüler individuell verwaltet werden.</p><h2 id="anlegen-neuer-einwilligungen" tabindex="-1">Anlegen neuer Einwilligungen <a class="header-anchor" href="#anlegen-neuer-einwilligungen" aria-label="Permalink to &quot;Anlegen neuer Einwilligungen&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/kataloge-dsgvo-01.png"><img src="'+g+'" alt="Verwaltung der DSGVO-Einwilligungen unter Kataloge ➜ DSGVO-Einwilligungen." loading="lazy"></a></p><p><em>Verwaltung der DSGVO-Einwilligungen unter Kataloge ➜ DSGVO-Einwilligungen.</em></p><p>Durch Klick auf das <strong>+</strong> kann eine neue Einwilligung angelegt werden.</p><p>In der Spalte <strong>Bezeichnung</strong> kann die entsprechende Bezeichnung eingetragen werden.</p><p>In der Spalte <strong>Schlüssel</strong> kann eine Kurzbezeichnung für mehrerer Einwilligungen ausgewählt werden.</p><p>Die Spalte <strong>Personenart</strong> dient dazu, diejenige Gruppe, Schüler oder Lehrkräfte, auszuwählen, die die angelegte Einwilligungsart betreffen soll.</p><p>Die Einträge in der Spalte <strong>Sortierung</strong> legen wie bei allen Katalogen die Sortierung fest.</p>',14),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),a("Hinweis")]),e("p",null,'Bei Anlage einer neuen Einwilligungsart wird diese unmittelbar für alle Schülerinnen und Schüler im Reiter "Einwilligungen" angelegt. Dieser Prozess kann einige Zeit dauern.')],-1),i('<h2 id="sortierung-der-dsgvo-einwilligungen" tabindex="-1">Sortierung der DSGVO-Einwilligungen <a class="header-anchor" href="#sortierung-der-dsgvo-einwilligungen" aria-label="Permalink to &quot;Sortierung der DSGVO-Einwilligungen&quot;">​</a></h2><p>Bei Verwendung der <strong>Sortierung</strong> &quot;Bezeichnung&quot; sortiert das Programm alphabetisch, wobei alle Großbuchstaben vor den Kleinbuchstaben einsortiert werden. In dieser Reihenfolge werden die Einwilligungen auch in den entsprechenden Auwahlfeldern im Programm sortiert.</p><p><a href="/bilder/unterricht-kataloge/kataloge-dsgvo-02.png"><img src="'+o+'" alt="Individuelle Sortierung der DSGVO-Einwilligungen." loading="lazy"></a></p><p><em>Individuelle Sortierung der DSGVO-Einwilligungen.</em></p><p>Ist eine <strong>individuelle Sortierung</strong> gewünscht, so kann dies eingestellt werden. Die Pfeile am linken Rand werden damit aktiviert und erlauben eine individuelle Reihenfolge. Im Beispiel dargestellt ist die Verschiebung der neu angelegten Einwilligungsart &quot;Verwendung Namen Presse&quot;.</p><h2 id="bearbeiten-von-dsgvo-einwilligungen" tabindex="-1">Bearbeiten von DSGVO-Einwilligungen <a class="header-anchor" href="#bearbeiten-von-dsgvo-einwilligungen" aria-label="Permalink to &quot;Bearbeiten von DSGVO-Einwilligungen&quot;">​</a></h2><p>Durch einen Doppelklick in das entsprechende Feld in der Spalte <strong>Bezeichnung</strong> kann die Bezeichnung bereits angelegter Einwilligungsarten geändert werden.</p><p>Ebenso können auch die Inhalte der Felder <strong>Schlüssel</strong> und die <strong>Personenart</strong> sowie die <strong>Beschreibung</strong> geändert werden.</p><p>Ein Klick auf das <strong>-</strong> löscht die angelegte Einwilligung nach Bestätigung einer Dialogabfrage.</p><h2 id="export-in-eine-excel-tabelle" tabindex="-1">Export in eine Excel-Tabelle <a class="header-anchor" href="#export-in-eine-excel-tabelle" aria-label="Permalink to &quot;Export in eine Excel-Tabelle&quot;">​</a></h2><p>Durch Klick auf <strong>Excel-Export</strong> und <strong>Speichern</strong> im folgenden Fenster kann die aktuelle Ansicht in eine Excel-Tabelle exportiert werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=DSGVO-Einwilligungen_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5453.</p>',13)])])}const S=r(s,[["render",d]]);export{k as __pageData,S as default};
